"""Render backtest and audit results as markdown under docs/ (generated, do not edit by hand)."""

from __future__ import annotations

import json
import sqlite3

from . import config, db
from .features import INTERACTIONS, NAMES

HEADER = "<!-- Generated by `tennisscout report`. Do not edit by hand; re-run the pipeline instead. -->\n"


def _f(x, nd=4):
    return "–" if x is None else f"{x:.{nd}f}"


def _pct(x, nd=1):
    return "–" if x is None else f"{100 * x:.{nd}f}%"


def _metrics_table(rows: list[tuple[str, dict]]) -> list[str]:
    out = ["| Model | n | Accuracy | Brier | Log loss | ECE |", "|---|---:|---:|---:|---:|---:|"]
    for name, m in rows:
        if not m.get("n"):
            continue
        out.append(f"| {name} | {m['n']:,} | {_pct(m['accuracy'])} | {_f(m['brier'])} | {_f(m['log_loss'])} | {_f(m['ece'])} |")
    return out


def backtest_md(r: dict) -> str:
    v, t = r["validation_years"], r["test_years"]
    h = r["test_headline"]
    cfg = r["selected_config"]
    L = [HEADER, "# Backtest: pre-match win probability", ""]
    L += [
        f"Chronological replay of {r.get('n_usable_matches', r['n_scorable_matches']):,} singles matches "
        f"(TML-Database 1968–Jan 2026, API-Tennis ATP after that and Challenger/qualifying from 2019), of which "
        f"{r['n_scorable_matches']:,} are tour-level main draw and are the only ones scored. Each match is predicted "
        "from ratings that have absorbed only earlier matches, then it updates them. "
        f"Model choices were made on **{v[0]} – {v[1]}** (validation) and scored on **{t[0]} – {t[1]}** (test). "
        + (f"The **forward** window ({r['forward_window'][0]} on) is API-Tennis data that no choice ever saw." if r.get("forward_window") else ""),
        "",
        "Excluded from both rating updates and scoring: walkovers, defaults, unknown results, and every row whose "
        "player identity failed a check (ID/name conflict, unknown or missing ID, placeholder player).",
        "",
        "## Test window, headline",
        "",
    ]
    L += _metrics_table([
        ("Coin flip", h["coin_flip"]),
        (f"Ranking logistic (β={h['ranking_logistic']['beta']:.3f}, fitted on validation)", h["ranking_logistic"]),
        ("Elo, overall only", h["elo_overall"]),
        ("Elo, 50/50 surface blend (FiveThirtyEight-style)", h["elo_538_blend"]),
        ("Elo, selected on validation", h["elo_selected"]),
        ("Serve/return ratings + Markov chain", h["serve_return"]),
        ("**Elo + serve/return blend (fitted on validation)**", h["elo_sr_blend"]),
    ])
    fh = r.get("forward_headline")
    if fh:
        L += ["", f"## Forward holdout ({r['forward_window'][0]} on, tour main draw, never used for any choice)", ""]
        L += _metrics_table([
            ("Coin flip", fh["coin_flip"]),
            ("Elo, overall only", fh["elo_overall"]),
            ("Elo, 50/50 surface blend", fh["elo_538_blend"]),
            ("Elo, selected", fh["elo_selected"]),
            ("Serve/return + Markov", fh["serve_return"]),
            ("**Elo + serve/return blend (served)**", fh["elo_sr_blend"]),
        ])
        fg = r["forward_blend_vs_elo"]
        L += ["", "Rankings are not in the API-Tennis feed, so there is no ranking baseline here. Blend vs Elo on these "
              f"matches: Brier gain {fg['brier']['gain']:.4f} ± {fg['brier']['se']:.4f}, log-loss gain "
              f"{fg['log_loss']['gain']:.4f} ± {fg['log_loss']['se']:.4f}.", "",
              "| Predicted | n | Mean prediction | Observed |", "|---|---:|---:|---:|"]
        L += [f"| {b['lo']:.1f}–{b['hi']:.1f} | {b['n']:,} | {_f(b['mean_p'], 3)} | {_f(b['observed'], 3)} |"
              for b in r["forward_serving_calibration"]]
    if r.get("data_variants"):
        L += ["", "## Data decision: Challenger and qualifying results", "",
              "API-Tennis adds Challenger and qualifying matches from 2019. They update ratings but are never scored. "
              "Whether to use them was decided on 2021–22 tour matches (where that data exists); 2023 on and the "
              f"forward window were not used for the choice. Chosen: **{r['data_choice']}**.", "",
              "| Data | 2021–22 (decision) | 2023 – Jan 2026 | Forward |", "|---|---:|---:|---:|"]
        for k, d in r["data_variants"].items():
            L.append(f"| {k} | " + " | ".join(_f(d[w].get("log_loss")) for w in ("decision_2021_22", "test_2023_on", "forward")) + " |")
        L += ["", "Log loss of the served blend; lower is better."]
    if r.get("scoreline_check"):
        L += ["", "## Scorelines: straight sets and tiebreaks", "",
              "The Markov chain also predicts how a match is won. Its point probabilities are anchored so that its "
              "match-win chance equals the served model's (the serve/return ratings set how serve-dominated the "
              "matchup is). Checked against actual scores (completed matches):", "",
              "| Window | n | Straight sets, predicted | observed | log loss | Tiebreaks per match, chain | calibrated | observed |",
              "|---|---:|---:|---:|---:|---:|---:|---:|"]
        scale = r.get("tiebreak_scale", 1.0)
        for w, sc in r["scoreline_check"].items():
            ss, tb = sc["straight_sets"], sc["tiebreaks_per_match"]
            cal = f"{tb['pred'] * scale:.3f}" if w in ("validation", "test", "forward") else "–"
            L.append(f"| {w} | {sc['n']:,} | {ss['mean_pred']:.3f} | {ss['observed']:.3f} | {_f(ss['log_loss'])} | {tb['pred']:.3f} | {cal} | {tb['observed']:.3f} |")
        L += ["", f"Match-level form on the day (sd {r.get('scoreline_form_sd', r['sr_config'].get('form_sd', 0))} on the logit "
              "scale, chosen on validation straight-sets log loss plus the tiebreak count's Poisson likelihood) is what "
              "brings these into line: with independent points the chain predicts too few straight sets and too many "
              "tiebreaks. `serve_return_only_test` is the same chain without the anchor. The calibrated tiebreak "
              f"count multiplies the chain's by {scale:.3f}, fitted on validation (so validation matches by construction)."]
    st = r.get("stack_experiment")
    if st:
        L += ["", "## Context features on top of the served model", "",
              "Greedy selection on validation of a logistic layer over the served probability. Candidates (see "
              "`features.py`): player differences " + ", ".join(f"`{f}`" for f in NAMES) + "; and context terms that "
              "rescale the served logit, " + ", ".join(f"`{f}`" for f in INTERACTIONS) + ". Selected: "
              + (", ".join(f"`{f}`" for f in st["features"]) or "none") + ".", "",
              "| Window | n | Served log loss | With features | Gain ± se |", "|---|---:|---:|---:|---:|"]
        for w in ("test", "test_2023_on", "forward"):
            if st.get(w):
                g = st[w]["gain"]["log_loss"]
                L.append(f"| {w} | {st[w]['base']['n']:,} | {_f(st[w]['base']['log_loss'])} | {_f(st[w]['stacked']['log_loss'])} | {g['gain']:.4f} ± {g['se']:.4f} |")
    wf = r.get("walk_forward") or {}
    if wf.get("validation_2016_18"):
        v = wf["validation_2016_18"]
        L += ["", "## Walk-forward refit of the context layer", "",
              "The layer's weights refit each January on the previous years only, against weights fixed on 2014–15. "
              f"Decided on 2016–18: fixed {_f(v['fixed']['log_loss'])}, yearly refit "
              + ", ".join(f"{k}-year window {_f(x)}" for k, x in v["by_years_back"].items())
              + f". {'Adopted' if wf['adopted'] else 'Not adopted'} ({wf['years_back']}-year window).", "",
              "| Window | n | Weights fixed on validation | Yearly refit | Gain ± se |", "|---|---:|---:|---:|---:|"]
        for w in ("test", "test_2023_on", "forward"):
            if wf.get(w):
                g = wf[w]["gain"]["log_loss"]
                L.append(f"| {w} | {wf[w]['walk_forward']['n']:,} | {_f(wf[w]['stacked_fixed']['log_loss'])} | "
                         f"{_f(wf[w]['walk_forward']['log_loss'])} | {g['gain']:.4f} ± {g['se']:.4f} |")
    L += [
        "",
        "Lower is better for Brier, log loss and ECE (expected calibration error, 10 bins). "
        "Market comparison: see `docs/markets.md`.",
        "",
        f"Selected Elo, completed matches only (retirements removed): "
        f"Brier {_f(r['test_selected_completed_only']['brier'])}, log loss {_f(r['test_selected_completed_only']['log_loss'])}, "
        f"n = {r['test_selected_completed_only']['n']:,}.",
        "",
        f"Serving model, chosen by validation log loss among the last three rows: **{r['serving_model']}**. "
        f"Blend: logit p = {r['blend_coef'][0]:.3f} × logit p_Elo + {r['blend_coef'][1]:.3f} × logit p_Markov "
        "(coefficients fitted on validation; the blend's validation score is therefore slightly optimistic).",
        "",
        "Blend vs selected Elo on the same test matches (positive = blend better): "
        + "; ".join(f"{k} gain {r['test_blend_vs_elo'][k]['gain']:.4f} ± {r['test_blend_vs_elo'][k]['se']:.4f} "
                    f"(z = {r['test_blend_vs_elo'][k]['z']:.1f})" for k in ("brier", "log_loss")) + ".",
        "",
        "## Serve/return model",
        "",
        "Each player has serve and return ratings on the logit scale; P(A wins a point on serve) = "
        "sigmoid(surface average + serve_A − return_B). Each match's serve points won update the ratings by a "
        "one-step Bayesian (Laplace) step, so players with few stat lines stay near the pool. The point "
        "probabilities go through a game → tiebreak → set → match Markov chain with each event's deciding-set "
        "rules (advantage sets, 12–12 and 10-point tiebreaks by Slam and year). Matches without a valid stat line "
        "still get a prediction but do not update the ratings.",
        "",
        "Prior and drift variances are chosen on the **blend's** validation log loss, because the blend is what is "
        "served; per-player surface offsets are then added only if they improve it further (they did).",
        "",
        "| prior_var | drift_var | surface_var | Markov alone, validation | Markov alone, test | Blend, validation |",
        "|---:|---:|---:|---:|---:|---:|",
    ]
    L += [f"| {g['config']['prior_var']} | {g['config']['drift_var']} | {g['config']['surface_var']} | {_f(g['validation']['log_loss'], 5)} | "
          f"{_f(g['test']['log_loss'], 5)} | {_f(g['blend_validation']['log_loss'], 5)} |" for g in r["sr_grid"]]
    L += [
        "",
        f"Calibration of the serving model ({r['serving_model']}), test window:",
        "",
        "| Predicted | n | Mean prediction | Observed win rate |",
        "|---|---:|---:|---:|",
    ]
    L += [f"| {b['lo']:.1f}–{b['hi']:.1f} | {b['n']:,} | {_f(b['mean_p'], 3)} | {_f(b['observed'], 3)} |" for b in r["test_serving_calibration"]]
    L += ["", "By confidence grade (serving model, test window):", ""]
    L += _metrics_table(list(r["test_serving_by_confidence"].items()))
    L += [
        "",
        "## How the Elo model was chosen",
        "",
        "Greedy forward selection: start from the FiveThirtyEight-style blend, try each single change, adopt the one "
        "that most improves **validation** log loss, repeat until nothing improves. Test numbers are shown for "
        "transparency only; they played no part in the choice.",
        "",
        "| Step | Validation log loss | Test log loss | Test Brier | Test ECE |",
        "|---|---:|---:|---:|---:|",
    ]
    for s in r["selection_steps"]:
        L.append(f"| {s['step']} | {_f(s['validation']['log_loss'], 5)} | {_f(s['test']['log_loss'], 5)} | {_f(s['test']['brier'], 5)} | {_f(s['test']['ece'])} |")
    L += [
        "",
        "Selected configuration: " + ", ".join(
            f"`{k}={cfg[k]}`" for k in ("surface_weight", "split_indoor_hard", "new_player_prior", "surface_init", "bo5_adjust", "pred_scale", "k_num", "k_offset", "k_shape")
        ) + ".",
        "",
        "<details><summary>Every candidate tried</summary>",
        "",
        "| From | Change | Validation log loss | Test log loss |",
        "|---|---|---:|---:|",
    ]
    for c in r["candidates_tried"]:
        L.append(f"| {c['from']} | {c['change']} | {_f(c['validation']['log_loss'], 5)} | {_f(c['test']['log_loss'], 5)} |")
    L += ["", "</details>", "", "## Calibration (selected Elo, test window)", "",
          "| Predicted | n | Mean prediction | Observed win rate |", "|---|---:|---:|---:|"]
    for b in r["test_calibration"]:
        L.append(f"| {b['lo']:.1f}–{b['hi']:.1f} | {b['n']:,} | {_f(b['mean_p'], 3)} | {_f(b['observed'], 3)} |")
    for title, key in (("By confidence grade", "test_by_confidence"), ("By tournament level", "test_by_level"),
                       ("By surface bucket", "test_by_bucket"), ("By best-of", "test_by_best_of"), ("By year", "test_by_year")):
        L += ["", f"## {title} (selected Elo, test window)", ""]
        L += _metrics_table(list(r[key].items()))
    L += [
        "",
        "Confidence grades: *high* = both players ≥ 50 prior tour matches and ≥ 15 on the surface; "
        "*medium* = both ≥ 15 overall; *low* = otherwise.",
        "",
    ]
    return "\n".join(L)


def venue_md(v: dict) -> list[str]:
    rows = v["rows"]
    ok = [r for r in rows if r["status"] == "checked" and r["elevation_ok"] and r["region_ok"]]
    L = ["## Venue table check", "",
         f"Run at {v['run_at']}. Each row of `metadata/venues.csv` was compared with Open-Meteo at its coordinates: "
         "terrain elevation from the 90 m DEM (agree within 60 m or 25%) and the IANA timezone's region. "
         f"{len(ok)} of {len(rows)} rows agree. This confirms the coordinates sit at the stated altitude and on the "
         "right continent, not that they point at the exact venue.", ""]
    bad = [r for r in rows if r not in ok]
    if bad:
        L += ["| Venue | From | Seed m | DEM m | Timezone | Status |", "|---|---:|---:|---:|---|---|"]
        L += [f"| {r['venue']} | {r['year_from']} | {r.get('seed_m', '–')} | {r.get('dem_m', '–')} | {r.get('timezone', '–')} | {r['status']} |" for r in bad]
        L.append("")
    return L


def audit_md(a: dict, venue_check: dict | None = None) -> str:
    pi, pt, cs, ss = a["population_identity"], a["population_timestamps"], a["cross_source"], a["sample_summary"]
    L = [HEADER, "# Data audit (first milestone)", ""]
    L += [f"Run at {a['run_at']}. Source snapshots:", ""]
    for s in a["snapshots"]:
        L.append(f"- `{s['snapshot_id']}`: {s['source']} revision {s['revision'][:12]} ({s['revision_date']}), collected {s['collected_at']}")
    L += ["", "## External services (probed live during the audit)", "", "| Service | URL | Reachable | Status / error |", "|---|---|---|---|"]
    for svc, probes in a["external_probes"].items():
        for p in probes:
            L.append(f"| {svc} | `{p['url'].split('?')[0]}` | {'yes' if p['reachable'] else 'no'} | {p['status'] or p['error']} |")
    L += ["", f"## Sample of {ss['n']} completed singles matches (2024–2025, stratified)", "",
          "Strata: " + ", ".join(f"{k} {v}" for k, v in ss["by_stratum"].items()) + ".", "",
          "| Check | Result |", "|---|---|"]
    rows = [
        ("Both players mapped to internal IDs", _pct(ss["both_players_internal_id"])),
        ("Identity check passed (ID and display name agree)", _pct(ss["identity_ok"])),
        ("Opponent, score and round present", _pct(ss["has_score_round"])),
        ("Serve/return stat line present", _pct(ss["has_serve_stats"])),
        ("Pre-match rankings present", _pct(ss["has_pre_match_ranks"])),
        ("Surface present", _pct(ss["has_surface"])),
        ("Indoor/outdoor flag present", f"{_pct(ss['has_indoor_flag'])} (tournament-level only; match-level roof status: {_pct(ss['indoor_flag_match_level'])})"),
        ("Altitude present", f"{_pct(ss['has_altitude_seed'])} (manual venue seed, checked against a DEM below)"),
        ("Outdoor matches with venue coordinates", f"{ss['outdoor_with_coordinates']} of {ss['outdoor_matches']}"),
        ("Outdoor matches with reconstructed weather joined", f"{ss['outdoor_weather_joined']} of {ss['outdoor_matches']} (Open-Meteo reanalysis, city-level, edition window)"),
        ("Event-time precision", ", ".join(f"{k}: {v}" for k, v in ss["event_time_precision"].items()) + f" (median window {ss['median_event_window_days']} days)"),
        ("Exact match date available (via linked MCP chart)", _pct(ss["exact_date_via_mcp"])),
        ("Start time of day available (via MCP)", _pct(ss["start_time_via_mcp"])),
        ("Publication timestamp", _pct(ss["has_publication_time"])),
        ("Collection timestamp", _pct(ss["has_collection_time"])),
        ("Point-by-point chart available", _pct(ss["point_by_point_available"])),
        ("Pre-match Elo prediction scored", _pct(ss["has_pre_match_prediction"])),
        ("Kalshi match market linked", _pct(ss["kalshi_market"]) + " (Kalshi ATP match markets start Aug 2025)"),
        ("Polymarket match market linked", _pct(ss["polymarket_market"]) + " (Polymarket head-to-head markets start Sep 2025)"),
    ]
    L += [f"| {k} | {v} |" for k, v in rows]
    st = pi["match_rows_by_identity_status"]
    L += ["", "## Identity (whole TML backbone)", "",
          "Match rows by identity status: " + ", ".join(f"{k} {v:,}" for k, v in sorted(st.items(), key=lambda kv: -kv[1])) + ". "
          "Rows that are not `ok` are kept in the database but excluded from ratings, training and scoring.", "",
          "ID/name conflicts (the source attached one player's ATP ID to another player's row):", ""]
    for c in pi["id_name_conflicts"]:
        L.append(f"- {c['year']} {c['tournament']} {c['round']}: {c['identity_note']}")
    L += ["", f"Homonyms among players with matches (same normalized name, different ATP IDs): {len(pi['homonym_names'])}, e.g. "
          + ", ".join(h["name"] for h in pi["homonym_names"][:8]) + ". Name lookups for these return all candidates.",
          "", f"Players seen under more than one display name: {pi['players_with_name_variants']:,}.", ""]
    L += ["## Timestamps (whole TML backbone)", "",
          "- Event-time precision: " + ", ".join(f"{k} {v:,}" for k, v in pt["event_time_precision"].items()) + ". "
          "Before 2026 the source dates only the tournament week, so each match's event time is a window.",
          f"- Rows with a publication timestamp: {pt['rows_with_publication_time']:,} of {pt['match_rows']:,}.",
          f"- Editions whose TML date is contradicted by exact-dated MCP charts: {pt['editions_with_dates_contradicted_by_mcp']}.",
          f"- Latest event in the mirror: {pt['latest_event_date']}.", ""]
    if a.get("market_coverage"):
        L += ["## Prediction markets", "",
              "Each exchange match market is linked to our matches on both players (internal IDs), a date window, "
              "the round when the exchange states it, and tournament name as a tie-break. Markets without a round "
              "(Polymarket, 2025-format Kalshi) must not predate the main draw, so qualifying meetings cannot link.", "",
              "| | Kalshi | Polymarket |", "|---|---:|---:|"]
        k, p = a["market_coverage"]["kalshi"], a["market_coverage"]["polymarket"]
        keys = sorted(set(k["status"]) | set(p["status"]), key=lambda x: -(k["status"].get(x, 0) + p["status"].get(x, 0)))
        L += [f"| Match events listed | {k['match_events']:,} | {p['match_events']:,} |",
              f"| First market date | {k['first_market_date']} | {p['first_market_date']} |"]
        L += [f"| {x} | {k['status'].get(x, 0):,} | {p['status'].get(x, 0):,} |" for x in keys]
        L += [f"| Our matches in the overlap window | {k['tml_matches_in_window']:,} | {p['tml_matches_in_window']:,} |",
              f"| … with a linked market | {k['tml_matches_with_market']:,} ({_pct(k['tml_matches_with_market'] / k['tml_matches_in_window'])}) | "
              f"{p['tml_matches_with_market']:,} ({_pct(p['tml_matches_with_market'] / p['tml_matches_in_window'])}) |",
              f"| Settled winner agrees with our data | {k['settled_winner_vs_tml'].get('agrees', 0):,} of {sum(k['settled_winner_vs_tml'].values()):,} | "
              f"{p['settled_winner_vs_tml'].get('agrees', 0):,} of {sum(p['settled_winner_vs_tml'].values()):,} |", ""]
        pr = a["market_price_resolution"]
        L += ["Price history around the match day, for a deterministic sample of linked markets:", "",
              "| | Kalshi | Polymarket |", "|---|---|---|"]
        def col(rows, f):
            return f(rows) if rows else "–"
        L += [
            f"| Markets sampled | {len(pr['kalshi'])} | {len(pr['polymarket'])} |",
            "| Median gap between observations | " + " | ".join(col(pr[x], lambda r: f"{sorted(q['median_gap_s'] or 0 for q in r)[len(r) // 2]} s") for x in ("kalshi", "polymarket")) + " |",
            "| Bid and ask available | " + " | ".join(col(pr[x], lambda r: f"{sum(q['has_bid_ask'] for q in r)} of {len(r)}") for x in ("kalshi", "polymarket")) + " |",
            "| Scheduled start known | " + " | ".join(col(pr[x], lambda r: f"{sum(1 for q in r if q['scheduled_start'])} of {len(r)}") for x in ("kalshi", "polymarket")) + " |",
            "| Observation in the hour before scheduled start | " + " | ".join(col(pr[x], lambda r: f"{sum(1 for q in r if q['obs_in_hour_before_start'])} of {sum(1 for q in r if q['scheduled_start'])}") for x in ("kalshi", "polymarket")) + " |",
            "",
            "Scheduled start is the exchange's own schedule, not first serve: no source here records first serve, "
            "and none records point or game timestamps, so in-play price paths cannot be joined.", "",
        ]
    fc = a.get("weather_forecast_check") or {}
    if fc.get("checked"):
        L += [f"Archived forecast check (Open-Meteo historical-forecast API, needed for leak-free pre-match conditions): "
              f"{'ok' if fc.get('status') == 200 else (fc.get('error') or fc.get('status'))}.", ""]
    L += ["## Cross-source linking (Match Charting Project → internal IDs)", "",
          "| Link status | All years | 2019 on |", "|---|---:|---:|"]
    keys = sorted(set(cs["charts_all_years"]) | set(cs["charts_2019_on"]), key=lambda k: -cs["charts_all_years"].get(k, 0))
    for k in keys:
        L.append(f"| {k} | {cs['charts_all_years'].get(k, 0):,} | {cs['charts_2019_on'].get(k, 0):,} |")
    L += ["", "Player-name resolution: " + ", ".join(f"{k} {v:,}" for k, v in sorted(cs["player_name_resolution"].items(), key=lambda kv: -kv[1])) + ".",
          "",
          f"Of {cs['linked']:,} linked charts, {cs['linked_surface_disagreements']} disagree with TML about the surface "
          f"({cs['linked_hard_vs_carpet']} are MCP 'Hard' vs TML 'Carpet'), and {cs['linked_with_start_time']:,} carry a start time.",
          "", "Name variants resolved only because the match-level join was unique (candidates for `metadata/player_aliases.csv` after review):", ""]
    for f in cs["alias_suggestions_from_unique_joins"][:20]:
        L.append(f"- MCP “{f['name']}” → {f['tml_name']} (`{f['player_id']}`), {f['charts']} chart(s)")
    L.append("")
    if venue_check:
        L += venue_md(venue_check)
    return "\n".join(L)


def markets_md(m: dict) -> str:
    L = [HEADER, "# Model vs prediction markets", ""]
    L += [
        f"Served model: **{m['serving_model']}**. Each row is one of our tour main-draw matches with a linked exchange "
        "market and a scheduled start (API-Tennis start time, else the exchange's). The market probability for "
        "player 1 is read at a checkpoint and normalised across both players' contracts to remove the margin; the "
        "model probability is the pre-match prediction for the same match. The combined model is a logistic fit on "
        "the market and model logits, fitted on the earlier half of the rows and scored on the later half.",
        "",
        "| Checkpoint | n | Market Brier | Model Brier | Market log loss | Model log loss | Market gain ± se | "
        "Later half: market / model / combined log loss | Combined gain over market ± se |",
        "|---|---:|---:|---:|---:|---:|---:|---|---:|",
    ]

    def gain(g):
        return f"{g['log_loss']['gain']:.4f} ± {g['log_loss']['se']:.4f}" if g else "–"

    for key, c in m["comparisons"].items():
        lh = c["later_half"]
        L.append(f"| {key} | {c['n']:,} | {_f(c['market']['brier'])} | {_f(c['model']['brier'])} | "
                 f"{_f(c['market']['log_loss'])} | {_f(c['model']['log_loss'])} | {gain(c.get('market_vs_model'))} | "
                 f"{_f(lh['market']['log_loss'])} / {_f(lh['model']['log_loss'])} / {_f(lh['combined']['log_loss'])} (n={lh['n']:,}) | "
                 f"{gain(lh.get('combined_vs_market'))} |")
    L += ["", "## Trading check (Kalshi, one hour before the scheduled start)", "",
          "One contract on a player whenever the model probability exceeds the Kalshi ask plus taker fee by the "
          "threshold; settled at 1 or 0. Historical depth is not stored, so whether the size was available is not "
          "verified, and this is a research check, not a betting result.", "",
          "| Edge threshold | Bets | P&L (sum, $ per contract) ± se | ROI per bet |", "|---|---:|---:|---:|"]
    for k, t in m["trading"].items():
        se = f" ± {t['pnl_se']}" if t.get("pnl_se") else ""
        L.append(f"| {k} | {t['bets']:,} | {t['pnl_per_contract_sum']}{se} | {_pct(t['roi']) if t['roi'] is not None else '–'} |")
    L.append("")
    return "\n".join(L)


def write(conn: sqlite3.Connection) -> list[str]:
    config.DOCS_DIR.mkdir(parents=True, exist_ok=True)
    written = []
    bt = db.get_meta(conn, "backtest_result")
    if bt:
        p = config.DOCS_DIR / "backtest.md"
        p.write_text(backtest_md(json.loads(bt)))
        written.append(str(p))
    me = db.get_meta(conn, "market_eval")
    if me:
        p = config.DOCS_DIR / "markets.md"
        p.write_text(markets_md(json.loads(me)))
        written.append(str(p))
    au = db.get_meta(conn, "audit_result")
    if au:
        p = config.DOCS_DIR / "data-audit.md"
        p.write_text(audit_md(json.loads(au), json.loads(db.get_meta(conn, "venue_check") or "null")))
        written.append(str(p))
    return written
